// Des: Tests for the safety ladder, caps, quiet hours and once-only keys
// Flo: read and dry change nothing > live posts once > repeat is skipped > caps and quiet hours block > unsure key refuses > failure before submit stays retryable
// I/O: real local Chrome (skipped when absent) + mock site > pass or fail (no leaks)
// Run: zig build test -Dfile=ru-task-runn-test.zig
// ===================================================================
const std = @import("std"); const rigz = @import("te-rigz-brow.zig"); const task = @import("ru-task-runn.zig"); const post = @import("ru-post-main.zig"); const dm = @import("ru-dmsg-main.zig");
fn has(rig: *rigz.Rig, needle: []const u8) bool { return std.mem.find(u8, rig.sink.items, needle) != null; }
test "read and dry-run change nothing, dry-run says so" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); var cx = rig.ctx(.read); try std.testing.expectEqual(task.Out.read, try post.postRun(&cx, .{ .text = "Hello ladder" })); cx = rig.ctx(.dry); try std.testing.expectEqual(task.Out.dry, try post.postRun(&cx, .{ .text = "Hello ladder" })); try std.testing.expectEqual(@as(usize, 0), rig.mock.recCnt()); try std.testing.expect(has(&rig, "dry-run: preview only")); try std.testing.expectEqual(@as(i64, 0), try rig.store.actCnt("post", 0)); }
test "live posts once; the same text again is skipped, caps counter = 1" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); var cx = rig.ctx(.live); try std.testing.expectEqual(task.Out.done, try post.postRun(&cx, .{ .text = "Hello ladder" })); try std.testing.expectEqualStrings("Hello ladder", rig.waitRec("post", 3000).?); try std.testing.expectEqual(task.Out.dupe, try post.postRun(&cx, .{ .text = "Hello ladder" })); try std.testing.expectEqual(@as(usize, 1), rig.mock.recNum("post")); try std.testing.expectEqual(@as(i64, 1), try rig.store.actCnt("post", 0)); }
test "daily cap stops the next post" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); rig.conf.capz_post_dayz = 1; var cx = rig.ctx(.live); _ = try post.postRun(&cx, .{ .text = "first" }); try std.testing.expectError(error.CapHit, post.postRun(&cx, .{ .text = "second" })); _ = rig.waitRec("post", 3000).?; try std.testing.expectEqual(@as(usize, 1), rig.mock.recNum("post")); }
test "warm-up shrinks the cap for a new account" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); rig.conf.warm_dayz_coun = 14; rig.conf.capz_post_dayz = 3; var cx = rig.ctx(.live); cx.now_fix = 86400000 * 100; _ = try post.postRun(&cx, .{ .text = "one" }); try std.testing.expectError(error.CapHit, post.postRun(&cx, .{ .text = "two" })); }
test "quiet hours block live, dry-run only warns" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); rig.conf.quie_hour_rang = .{ 0, 23 }; rig.conf.quie_zone_minu = 0; var cx = rig.ctx(.live); cx.now_fix = 12 * 3600000; try std.testing.expectError(error.QuietHour, post.postRun(&cx, .{ .text = "night" })); cx = rig.ctx(.dry); cx.now_fix = 12 * 3600000; try std.testing.expectEqual(task.Out.dry, try post.postRun(&cx, .{ .text = "night" })); try std.testing.expect(has(&rig, "a live run would stop now")); try std.testing.expectEqual(@as(usize, 0), rig.mock.recCnt()); }
test "risky act needs --force, then goes through" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); var cx = rig.ctx(.live); try std.testing.expectError(error.NeedApprove, dm.friendRun(&cx, .{ .url = "/profile/9" })); try std.testing.expectEqual(@as(usize, 0), rig.mock.recCnt()); cx = rig.ctx(.force); try std.testing.expectEqual(task.Out.done, try dm.friendRun(&cx, .{ .url = "/profile/9" })); try std.testing.expectEqualStrings("9", rig.waitRec("friend", 3000).?); }
test "a key left pending (crash after submit) refuses, unlock reopens" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); var cx = rig.ctx(.live); const hsh = try task.hashHex(&cx, "crashed text"); const key = try std.fmt.allocPrint(cx.aren, "post|/|{s}", .{hsh}); try std.testing.expectEqual(@import("st-stat-main.zig").Take.go, try rig.store.keyTake(key, 1)); try std.testing.expectError(error.Dupe, post.postRun(&cx, .{ .text = "crashed text" })); try std.testing.expectEqual(@as(usize, 0), rig.mock.recCnt()); }
test "failure before submit keeps the key free: fix the label and retry works" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); rig.conf.retr_coun_maxz = 1; const good = rig.conf.labl_post_open; rig.conf.labl_post_open = &.{"zzz no such"}; var cx = rig.ctx(.live); try std.testing.expectError(error.NoElement, post.postRun(&cx, .{ .text = "retry me" })); try std.testing.expectEqual(@as(usize, 0), rig.mock.recCnt()); rig.conf.labl_post_open = good; cx = rig.ctx(.live); try std.testing.expectEqual(task.Out.done, try post.postRun(&cx, .{ .text = "retry me" })); try std.testing.expectEqualStrings("retry me", rig.waitRec("post", 3000).?); }
test "halt page mid-flow: nothing written, error is Halted" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); var cx = rig.ctx(.live); try std.testing.expectError(error.Halted, post.postTo(&cx, "x", "/checkpoint/5/", .post)); try std.testing.expectEqual(@as(usize, 0), rig.mock.recCnt()); }
